require "rails_helper"

RSpec.describe Timekeeping::LegacyAuditConversion do
  it "refuses a username-only legacy author instead of relabelling it as the system actor" do
    entries_by_id = { 7 => { "id" => 7, "company_id" => 1, "created_at" => Time.utc(2026, 9, 1) } }
    audit = {
      id: 900, action: "update", associated_type: "Company", associated_id: 1, auditable_id: 7,
      user_type: nil, user_id: nil, username: "legacy-importer",
      audited_changes: { "duration" => [60.0, 90.0] }, created_at: Time.utc(2026, 9, 2)
    }

    # Issue: "Keep its company, author, action, original `created_at` and change values
    # (before and after from `audited_changes`), and set `entry_created_at` from the entry."
    # A named author must never become the anonymous system actor.
    result = described_class.convert(audits: [audit], entries_by_id:)

    expect(result[:rows]).to be_empty
    expect(result[:refusals].keys).to eq([1])
    expect(result[:refusals][1].join(" ")).to include("legacy-importer")
  end
end

